class sync_fifo_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(sync_fifo_scoreboard)
 
  uvm_analysis_imp #(sync_fifo_item, sync_fifo_scoreboard) ap_imp;
 
  // Reference Model Storage
  logic [7:0] exp_q[$];
  logic [7:0] expected_rd_data;   // mirrors the DUT's registered rd_data
 
  function new(string name="sync_fifo_scoreboard", uvm_component parent=null);
    super.new(name, parent);
  endfunction
 
  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap_imp = new("ap_imp", this);
  endfunction
 
  function void write(sync_fifo_item item);
    bit eff_rd, eff_wr;
    bit exp_full, exp_empty;
 
    // ─── 1. Reset handling ────────────────────────────────────
    if (!item.rst_n) begin
      exp_q.delete();
      expected_rd_data = 8'h0;
      return;
    end
 
    // ─── 2. Compute expected output state for THIS cycle ──────
    // These reflect the model state as it stands BEFORE we apply
    // this cycle's inputs — i.e. the DUT outputs that result from
    // the previous transaction, which is what we should be seeing.
    exp_full  = (exp_q.size() == 8);
    exp_empty = (exp_q.size() == 0);
 
    if (item.full !== exp_full) begin
      `uvm_error("SCBD_FULL_MISMATCH",
        $sformatf("Act: %0b, Exp: %0b (qsize=%0d)",
                  item.full, exp_full, exp_q.size()))
    end
 
    if (item.empty !== exp_empty) begin
      `uvm_error("SCBD_EMPTY_MISMATCH",
        $sformatf("Act: %0b, Exp: %0b (qsize=%0d)",
                  item.empty, exp_empty, exp_q.size()))
    end
 
    if (item.rd_data !== expected_rd_data) begin
      `uvm_error("SCBD_DATA_MISMATCH",
        $sformatf("Act: %0h, Exp: %0h", item.rd_data, expected_rd_data))
    end
 
    // ─── 3. Apply this cycle's inputs to the model ────────────
    // Use the same "effective enable" semantics as the RTL so that
    // simultaneous R+W on a full FIFO commits both transactions.
    eff_rd = item.r_en && !exp_empty;
    eff_wr = item.w_en && (!exp_full || eff_rd);
 
    // The read happens "first" in the sense that the slot it frees
    // is what allows the write to proceed. The order of these two
    // queue operations doesn't matter for state, but the data the
    // read pulls is the OLD head, before the write pushes its new
    // value at the tail.
    if (eff_rd) begin
      // Capture the value the DUT will present on rd_data NEXT cycle.
      expected_rd_data = exp_q.pop_front();
    end
    if (eff_wr) begin
      exp_q.push_back(item.wr_data);
    end
  endfunction
endclass

